import {
  memo,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';

import { isEmpty, uniqBy } from 'lodash';

import { useTabIsRefreshingFocused } from '@onekeyhq/components';
import backgroundApiProxy from '@onekeyhq/kit/src/background/instance/backgroundApiProxy';
import type { IDBAccount } from '@onekeyhq/kit-bg/src/dbs/local/types';
import type { IAllNetworkAccountInfo } from '@onekeyhq/kit-bg/src/services/ServiceAllNetwork/ServiceAllNetwork';
import { getNetworkIdsMap } from '@onekeyhq/shared/src/config/networkIds';
import {
  POLLING_DEBOUNCE_INTERVAL,
  POLLING_INTERVAL_FOR_NFT,
} from '@onekeyhq/shared/src/consts/walletConsts';
import {
  EAppEventBusNames,
  appEventBus,
} from '@onekeyhq/shared/src/eventBus/appEventBus';
import { EHomeTab } from '@onekeyhq/shared/types';
import type {
  IAccountNFT,
  IFetchAccountNFTsResp,
} from '@onekeyhq/shared/types/nft';

import { useAllNetworkRequests } from '../../../hooks/useAllNetwork';
import { usePromiseResult } from '../../../hooks/usePromiseResult';
import { useAccountOverviewActions } from '../../../states/jotai/contexts/accountOverview';
import { useActiveAccount } from '../../../states/jotai/contexts/accountSelector';
import {
  useNFTListActions,
  withNFTListProvider,
} from '../../../states/jotai/contexts/nftList';
import { NFTListView } from '../components/NFTListView';
import { onHomePageRefresh } from '../components/PullToRefresh';

const networkIdsMap = getNetworkIdsMap();

function NFTListContainer() {
  const { isFocused, isHeaderRefreshing, setIsHeaderRefreshing } =
    useTabIsRefreshingFocused();
  const { updateAllNetworksState } = useAccountOverviewActions().current;
  const { updateSearchKey } = useNFTListActions().current;
  const [nftListState, setNftListState] = useState({
    initialized: false,
    isRefreshing: false,
  });
  const [nftList, setNftList] = useState<IAccountNFT[]>([]);

  const {
    activeAccount: { account, network, wallet },
  } = useActiveAccount({ num: 0 });

  // Owner this list is showing. `Tabs.Container` no longer remounts on an
  // account switch (OK-63873), so the local `nftList` survives it: drop the
  // previous owner's rows in the same commit the owner changes (layout effect,
  // before paint) and let every async writer bail when its captured owner is
  // no longer current, otherwise a slow read/fetch for the old owner would
  // land on the new one.
  const ownerKey = `${account?.id ?? ''}|${network?.id ?? ''}|${
    wallet?.id ?? ''
  }`;
  const ownerKeyRef = useRef(ownerKey);
  ownerKeyRef.current = ownerKey;
  const prevOwnerKeyRef = useRef(ownerKey);
  useLayoutEffect(() => {
    if (prevOwnerKeyRef.current === ownerKey) {
      return;
    }
    prevOwnerKeyRef.current = ownerKey;
    setNftList([]);
    setNftListState({
      initialized: false,
      isRefreshing: true,
    });
  }, [ownerKey]);
  // The All Networks callbacks below only know the account and network of the
  // run they belong to. After a switch the previous owner's fan-out keeps
  // running (the new owner's run queues behind it), so they check the live
  // owner before writing.
  const activeOwnerRef = useRef<{ accountId?: string; networkId?: string }>({});
  activeOwnerRef.current = { accountId: account?.id, networkId: network?.id };
  const isActiveOwner = useCallback(
    (accountId?: string, networkId?: string) =>
      activeOwnerRef.current.accountId === accountId &&
      activeOwnerRef.current.networkId === networkId,
    [],
  );

  const { run } = usePromiseResult(
    async () => {
      if (!account || !network) return;

      if (network.isAllNetworks) return;

      const capturedOwnerKey = ownerKeyRef.current;

      appEventBus.emit(EAppEventBusNames.TabListStateUpdate, {
        isRefreshing: true,
        type: EHomeTab.NFT,
        accountId: account.id,
        networkId: network.id,
      });

      await backgroundApiProxy.serviceNFT.abortFetchAccountNFTs();
      const r = await backgroundApiProxy.serviceNFT.fetchAccountNFTs({
        accountId: account.id,
        networkId: network.id,
        saveToLocal: true,
      });

      if (ownerKeyRef.current !== capturedOwnerKey) {
        return r.data;
      }

      setNftListState({
        initialized: true,
        isRefreshing: false,
      });
      setIsHeaderRefreshing(false);

      setNftList(r.data);

      appEventBus.emit(EAppEventBusNames.TabListStateUpdate, {
        isRefreshing: false,
        type: EHomeTab.NFT,
        accountId: account.id,
        networkId: network.id,
      });

      return r.data;
    },
    [account, network, setIsHeaderRefreshing],
    {
      overrideIsFocused: (isPageFocused) => isPageFocused && isFocused,
      debounced: POLLING_DEBOUNCE_INTERVAL,
      pollingInterval: POLLING_INTERVAL_FOR_NFT,
    },
  );

  const isAllNetworkManualRefresh = useRef(false);
  const handleAllNetworkRequests = useCallback(
    async ({
      accountId,
      networkId,
      allNetworkDataInit,
      dbAccount,
      isRunCurrent,
    }: {
      accountId: string;
      networkId: string;
      allNetworkDataInit?: boolean;
      dbAccount?: IDBAccount;
      isRunCurrent?: () => boolean;
    }) => {
      const r = await backgroundApiProxy.serviceNFT.fetchAccountNFTs({
        dbAccount,
        accountId,
        networkId,
        isAllNetworks: true,
        isManualRefresh: isAllNetworkManualRefresh.current,
        allNetworksAccountId: account?.id,
        allNetworksNetworkId: network?.id,
        saveToLocal: true,
      });
      // A fan-out superseded by an enabled-network change writes nothing; the
      // run that replaced it reads the manual-refresh flag for its own requests.
      if (isRunCurrent?.() === false) {
        return r;
      }
      // Neither does the previous owner's fan-out after a switch: its
      // `isSameAllNetworksAccountData` compares against the owner the request
      // started for, so it still passes. Its manual refresh is spent, though:
      // the next owner's queued run must not inherit a forced fetch.
      if (!isActiveOwner(account?.id, network?.id)) {
        isAllNetworkManualRefresh.current = false;
        return r;
      }
      if (
        !allNetworkDataInit &&
        r.networkId === networkIdsMap.onekeyall &&
        r.isSameAllNetworksAccountData
      ) {
        setNftList((prev) =>
          uniqBy(
            [...prev, ...r.data],
            (nft) => `${nft.collectionAddress}_${nft.itemId}`,
          ),
        );
        setNftListState({
          initialized: true,
          isRefreshing: false,
        });
      }

      isAllNetworkManualRefresh.current = false;
      return r;
    },
    [account?.id, isActiveOwner, network?.id],
  );

  const handleAllNetworkRequestsFinished = useCallback(
    async ({
      accountId,
      networkId,
    }: {
      accountId?: string;
      networkId?: string;
    }) => {
      appEventBus.emit(EAppEventBusNames.TabListStateUpdate, {
        isRefreshing: false,
        type: EHomeTab.NFT,
        accountId: accountId ?? '',
        networkId: networkId ?? '',
      });
    },
    [],
  );

  const handleAllNetworkRequestsStarted = useCallback(
    async ({
      accountId,
      networkId,
    }: {
      accountId?: string;
      networkId?: string;
    }) => {
      appEventBus.emit(EAppEventBusNames.TabListStateUpdate, {
        isRefreshing: true,
        type: EHomeTab.NFT,
        accountId: accountId ?? '',
        networkId: networkId ?? '',
      });
    },
    [],
  );

  const handleClearAllNetworkData = useCallback(() => setNftList([]), []);

  const handleAllNetworkCacheRequests = useCallback(
    async ({
      dbAccount,
      accountId,
      networkId,
    }: {
      dbAccount?: IDBAccount;
      accountId: string;
      networkId: string;
    }) => {
      const localNFTs = await backgroundApiProxy.serviceNFT.getAccountLocalNFTs(
        {
          dbAccount,
          accountId,
          networkId,
        },
      );
      if (isEmpty(localNFTs)) {
        return null;
      }
      return localNFTs;
    },
    [],
  );

  const handleAllNetworkCacheData = useCallback(
    async ({
      data,
      accountId,
      networkId,
    }: {
      data: IAccountNFT[];
      accountId: string;
      networkId: string;
    }) => {
      if (!isActiveOwner(accountId, networkId)) {
        return;
      }
      const allNFTs = data.flat();
      if (!isEmpty(allNFTs)) {
        setNftList(allNFTs);
        setNftListState({
          initialized: true,
          isRefreshing: false,
        });
      }
    },
    [isActiveOwner],
  );

  const handleAllNetworkAccountsData = useCallback(
    ({ allAccounts }: { allAccounts: IAllNetworkAccountInfo[] }) => {
      updateAllNetworksState({
        visibleCount: uniqBy(allAccounts, 'networkId').length,
      });
    },
    [updateAllNetworksState],
  );

  const {
    run: runAllNetworkRequests,
    result: allNetworksResult,
    isEmptyAccount,
  } = useAllNetworkRequests<IFetchAccountNFTsResp>({
    accountId: account?.id,
    networkId: network?.id,
    walletId: wallet?.id,
    isAllNetworks: network?.isAllNetworks,
    allNetworkRequests: handleAllNetworkRequests,
    allNetworkCacheRequests: handleAllNetworkCacheRequests,
    allNetworkCacheData: handleAllNetworkCacheData,
    clearAllNetworkData: handleClearAllNetworkData,
    allNetworkAccountsData: handleAllNetworkAccountsData,
    isNFTRequests: true,
    onStarted: handleAllNetworkRequestsStarted,
    onFinished: handleAllNetworkRequestsFinished,
  });

  const handleRefreshAllNetworkData = useCallback(() => {
    isAllNetworkManualRefresh.current = true;
    void runAllNetworkRequests();
  }, [runAllNetworkRequests]);

  useEffect(() => {
    if (allNetworksResult) {
      let allNetworksNftList: IAccountNFT[] = [];
      for (const r of allNetworksResult) {
        allNetworksNftList = allNetworksNftList.concat(r.data);
      }
      setNftList(
        uniqBy(
          allNetworksNftList,
          (nft) => `${nft.collectionAddress}_${nft.itemId}`,
        ),
      );
    }
  }, [allNetworksResult]);

  useEffect(() => {
    const initNFTsState = async (accountId: string, networkId: string) => {
      updateSearchKey('');
      void backgroundApiProxy.serviceNFT.updateCurrentAccount({
        networkId,
        accountId,
      });

      if (network?.isAllNetworks) {
        return;
      }

      const capturedOwnerKey = ownerKeyRef.current;
      const localNFTs = await backgroundApiProxy.serviceNFT.getAccountLocalNFTs(
        {
          accountId,
          networkId,
        },
      );
      // A faster owner switch took over during the read.
      if (ownerKeyRef.current !== capturedOwnerKey) {
        return;
      }

      if (!isEmpty(localNFTs)) {
        setNftList(localNFTs);
        setNftListState({
          initialized: true,
          isRefreshing: false,
        });
      } else {
        setNftListState({
          initialized: false,
          isRefreshing: true,
        });
      }
    };
    if (account?.id && network?.id && wallet?.id) {
      void initNFTsState(account.id, network.id);
    }
  }, [
    account?.id,
    network?.id,
    network?.isAllNetworks,
    updateSearchKey,
    wallet?.id,
  ]);

  useEffect(() => {
    if (isHeaderRefreshing) {
      void run();
    }
  }, [isHeaderRefreshing, run]);

  useEffect(() => {
    if (network?.isAllNetworks && isEmptyAccount) {
      setNftList([]);
      setNftListState({
        initialized: true,
        isRefreshing: false,
      });
    }
  }, [isEmptyAccount, network?.isAllNetworks]);

  useEffect(() => {
    const refresh = () => {
      if (network?.isAllNetworks) {
        void handleRefreshAllNetworkData();
      } else {
        void run();
      }
    };

    const fn = () => {
      if (isFocused) {
        refresh();
      }
    };
    appEventBus.on(EAppEventBusNames.AccountDataUpdate, fn);
    appEventBus.on(EAppEventBusNames.NetworkDeriveTypeChanged, fn);
    return () => {
      appEventBus.off(EAppEventBusNames.AccountDataUpdate, fn);
      appEventBus.off(EAppEventBusNames.NetworkDeriveTypeChanged, fn);
    };
  }, [handleRefreshAllNetworkData, isFocused, network?.isAllNetworks, run]);

  return (
    <NFTListView
      onRefresh={onHomePageRefresh}
      data={nftList ?? []}
      isLoading={nftListState.isRefreshing}
      initialized={nftListState.initialized}
      isAllNetworks={network?.isAllNetworks}
    />
  );
}

const NFTListContainerWithProvider = memo(
  withNFTListProvider(NFTListContainer),
);
NFTListContainerWithProvider.displayName = 'NFTListContainerWithProvider';

export { NFTListContainerWithProvider };
